/* ===== THE TOILET GAME — shared helpers (prepended to each scene) ===== */
function TTG_load() {
  var S = window.__ttg_save;
  if (S) return S;
  S = { coins: 0, xp: 0, pinchBest: 0, pinchGames: 0, runs: 0, dumps: 0,
        streak: 0, longest: 0, lastDump: "", sfx: true, music: true };
  try {
    var st = gdjs.evtTools.storage;
    if (st.elementExistsInJSONFile("ToiletGame", "save")) {
      var o = JSON.parse(st.readStringFromJSONFile("ToiletGame", "save", "{}"));
      for (var k in o) { if (k in S) S[k] = o[k]; }
    }
  } catch (e) {}
  window.__ttg_save = S;
  return S;
}
function TTG_save() {
  try {
    gdjs.evtTools.storage.writeStringInJSONFile("ToiletGame", "save",
      JSON.stringify(window.__ttg_save));
  } catch (e) {}
}
function TTG_level(xp) { return 1 + Math.floor(Math.sqrt(Math.max(0, xp) / 200)); }
function TTG_one(name) { var a = runtimeScene.getObjects(name); return a.length ? a[0] : null; }
function TTG_cur() {
  var i = gdjs.evtTools.input;
  return { x: i.getCursorX(runtimeScene, "", 0), y: i.getCursorY(runtimeScene, "", 0) };
}
function TTG_hit(o, x, y, pad) {
  pad = (pad === undefined) ? 40 : pad;
  var hw = o.getWidth() / 2 + pad, hh = o.getHeight() / 2 + pad;
  return Math.abs(x - o.getX()) <= hw && Math.abs(y - o.getY()) <= hh;
}
function TTG_snd(f, vol) {
  try {
    var S = window.__ttg_save;
    if (S && !S.sfx) return;
    gdjs.evtTools.sound.playSound(runtimeScene, f, false, vol || 90, 1);
  } catch (e) {}
}
function TTG_go(scene) {
  gdjs.evtTools.runtimeScene.replaceScene(runtimeScene, scene, false);
}
/* Button wiring: defs=[{obj,s,fn}]. Returns {down,x,y,pressed,released}.
   G must have prevDown/px/py/armed fields. */
function TTG_buttons(G, defs) {
  var c = TTG_cur();
  var down = gdjs.evtTools.input.isMouseButtonPressed(runtimeScene, "Left");
  var pressed = down && !G.prevDown;
  var released = !down && G.prevDown;
  if (pressed) {
    G.px = c.x; G.py = c.y; G.armed = null;
    for (var i = 0; i < defs.length; i++) {
      var b = defs[i];
      if (b.obj && TTG_hit(b.obj, c.x, c.y)) {
        G.armed = b; b.obj.setScale(b.s * 0.92); break;
      }
    }
  } else if (released) {
    if (G.armed) {
      var a = G.armed; G.armed = null; a.obj.setScale(a.s);
      if (TTG_hit(a.obj, c.x, c.y)) { TTG_snd("click.wav", 70); a.fn(); }
    }
  }
  G.prevDown = down;
  return { down: down, x: c.x, y: c.y, pressed: pressed, released: released };
}

