/* ===== PINCH scene — merge puzzle ("Merge, don't clog.") ===== */
(function () {
var S = TTG_load();
var TS = 240, PITCH = 260, X0 = 30, Y0 = 560;
var TILE_RGB = ["58;74;107","46;125;140","0;184;212","0;229;160","124;77;255",
  "213;0;249","255;109;0","255;171;0","255;215;64","255;255;141","255;255;255"];
function cellX(i){ return X0 + (i % 4) * PITCH + TS / 2; }
function cellY(i){ return Y0 + ((i / 4) | 0) * PITCH + TS / 2; }

var G = window.__pinch;
if (!G || G.rs !== runtimeScene) {
  G = { rs: runtimeScene, grid: new Array(16).fill(0), score: 0, over: false,
        won: false, tweens: [], parts: [], pops: [], pparts: [], ppops: [],
        prevDown: false, px: 0, py: 0, armed: null, swiping: false };
  window.__pinch = G;

  var bg = TTG_one("Bg"); bg.setX(540); bg.setY(960); bg.setScale(1); bg.setZOrder(0);

  var title = TTG_one("TitleText");
  title.setCharacterSize(64); title.setColor("0;229;255");
  title.setText("PINCH"); title.setX(150); title.setY(100); title.setZOrder(3);

  G.scoreT = TTG_one("ScoreText");
  G.scoreT.setCharacterSize(54); G.scoreT.setColor("255;255;255");
  G.scoreT.setText("SCORE: 0"); G.scoreT.setX(540); G.scoreT.setY(90); G.scoreT.setZOrder(3);
  G.bestT = TTG_one("BestText");
  G.bestT.setCharacterSize(36); G.bestT.setColor("255;215;64");
  G.bestT.setText("BEST: " + S.pinchBest); G.bestT.setX(540); G.bestT.setY(165); G.bestT.setZOrder(3);

  var rb = TTG_one("RestartBtn"); rb.setX(905); rb.setY(85); rb.setScale(0.55); rb.setZOrder(3);
  var hb = TTG_one("HomeBtn"); hb.setX(905); hb.setY(190); hb.setScale(0.55); hb.setZOrder(3);
  G.defs = [
    { obj: rb, s: 0.55, fn: function(){ TTG_go("Pinch"); } },
    { obj: hb, s: 0.55, fn: function(){ TTG_go("Home"); } }
  ];

  var sub = TTG_one("SubText");
  sub.setCharacterSize(38); sub.setColor("200;235;255");
  sub.setText("Merge matching pieces. Don't clog the board.");
  sub.setX(540); sub.setY(1670); sub.setZOrder(3);

  for (var i = 0; i < 16; i++) {
    var c = TTG_one("Cell" + i);
    c.setX(cellX(i)); c.setY(cellY(i)); c.setScale(1); c.setZOrder(1);
    var t = TTG_one("Tile" + i);
    t.setX(cellX(i)); t.setY(cellY(i)); t.setScale(1); t.setZOrder(2);
    t.hide(true);
  }
  for (var p = 0; p < 12; p++) {
    var pt = TTG_one("Part" + p); pt.setZOrder(4); pt.hide(true);
    G.pparts.push({ obj: pt, x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1 });
  }
  for (var q = 0; q < 6; q++) {
    var pp = TTG_one("Pop" + q);
    pp.setCharacterSize(52); pp.setColor("255;255;255"); pp.setZOrder(5); pp.hide(true);
    G.ppops.push({ obj: pp, t: 0, dur: 0.7, active: false, y0: 0 });
  }

  /* game-over panel (hidden) */
  G.panel = TTG_one("Panel");
  G.panel.setX(540); G.panel.setY(960); G.panel.setScale(1); G.panel.setZOrder(10);
  G.panel.hide(true);
  G.ptitle = TTG_one("PTitle");
  G.ptitle.setCharacterSize(84); G.ptitle.setColor("255;215;64");
  G.ptitle.setText("CLOGGED!"); G.ptitle.setX(540); G.ptitle.setY(700); G.ptitle.setZOrder(11);
  G.ptitle.hide(true);
  G.pscore = TTG_one("PScore");
  G.pscore.setCharacterSize(52); G.pscore.setColor("255;255;255"); G.pscore.setZOrder(11);
  G.pscore.hide(true);
  G.pbest = TTG_one("PBest");
  G.pbest.setCharacterSize(40); G.pbest.setColor("0;229;255"); G.pbest.setZOrder(11);
  G.pbest.hide(true);
  G.pcoins = TTG_one("PCoins");
  G.pcoins.setCharacterSize(40); G.pcoins.setColor("0;229;160"); G.pcoins.setZOrder(11);
  G.pcoins.hide(true);
  var ag = TTG_one("AgainBtn"); ag.setX(540); ag.setY(1090); ag.setScale(1); ag.setZOrder(12);
  ag.hide(true);
  var ph = TTG_one("PanelHomeBtn"); ph.setX(540); ph.setY(1230); ph.setScale(1); ph.setZOrder(12);
  ph.hide(true);
  G.panelDefs = [
    { obj: ag, s: 1, fn: function(){ TTG_go("Pinch"); } },
    { obj: ph, s: 1, fn: function(){ TTG_go("Home"); } }
  ];

  spawnTile(); spawnTile();
  render();
  updateScore();
}

/* ---------- game logic ---------- */
function lines(dir) {
  var L = [], r, c;
  if (dir === "L") { for (r = 0; r < 4; r++) L.push([r*4, r*4+1, r*4+2, r*4+3]); }
  if (dir === "R") { for (r = 0; r < 4; r++) L.push([r*4+3, r*4+2, r*4+1, r*4]); }
  if (dir === "U") { for (c = 0; c < 4; c++) L.push([c, c+4, c+8, c+12]); }
  if (dir === "D") { for (c = 0; c < 4; c++) L.push([c+12, c+8, c+4, c]); }
  return L;
}
function spawnTile() {
  var empty = [];
  for (var i = 0; i < 16; i++) if (G.grid[i] === 0) empty.push(i);
  if (!empty.length) return;
  var i = empty[(Math.random() * empty.length) | 0];
  G.grid[i] = Math.random() < 0.9 ? 1 : 2;
  G.tweens.push({ obj: TTG_one("Tile" + i), t: 0, dur: 0.16, base: 1, amp: 0.25 });
  TTG_snd("spawn.wav", 45);
}
function canMove() {
  for (var i = 0; i < 16; i++) if (G.grid[i] === 0) return true;
  for (var r = 0; r < 4; r++) for (var c = 0; c < 4; c++) {
    var v = G.grid[r * 4 + c];
    if (c < 3 && G.grid[r * 4 + c + 1] === v) return true;
    if (r < 3 && G.grid[(r + 1) * 4 + c] === v) return true;
  }
  return false;
}
function render() {
  for (var i = 0; i < 16; i++) {
    var t = TTG_one("Tile" + i), v = G.grid[i];
    if (v <= 0) { t.hide(true); }
    else {
      t.hide(false); t.setAnimation(v - 1);
      t.setX(cellX(i)); t.setY(cellY(i)); t.setScale(1);
    }
  }
}
function updateScore() {
  G.scoreT.setText("SCORE: " + G.score);
  G.bestT.setText("BEST: " + Math.max(S.pinchBest, G.score));
}
function addPop(cell, exp) {
  var t = TTG_one("Tile" + cell);
  G.tweens.push({ obj: t, t: 0, dur: 0.2, base: 1, amp: 0.32 });
}
function burst(cell, exp) {
  var col = TILE_RGB[Math.min(exp - 1, 10)];
  var n = 0;
  for (var k = 0; k < G.pparts.length && n < 5; k++) {
    var p = G.pparts[k];
    if (p.life > 0) continue;
    n++;
    p.x = cellX(cell); p.y = cellY(cell);
    var a = Math.random() * Math.PI * 2, sp = 260 + Math.random() * 320;
    p.vx = Math.cos(a) * sp; p.vy = Math.sin(a) * sp - 200;
    p.life = p.max = 0.45 + Math.random() * 0.25;
    p.obj.setColor(col);
    p.obj.hide(false);
  }
}
function popup(text, cell) {
  for (var k = 0; k < G.ppops.length; k++) {
    var p = G.ppops[k];
    if (p.active) continue;
    p.active = true; p.t = 0;
    p.y0 = cellY(cell) - 40;
    p.obj.setText(text); p.obj.setX(cellX(cell)); p.obj.setY(p.y0);
    p.obj.setOpacity(255); p.obj.hide(false);
    return;
  }
}
function doMove(dir) {
  var old = G.grid.slice(), gained = 0, merges = [];
  var Ls = lines(dir);
  for (var li = 0; li < 4; li++) {
    var line = Ls[li], vals = [];
    for (var j = 0; j < 4; j++) { var v = G.grid[line[j]]; if (v > 0) vals.push(v); }
    var out = [];
    while (vals.length) {
      if (vals.length > 1 && vals[0] === vals[1]) {
        var nv = vals[0] + 1; out.push(nv);
        merges.push({ cell: line[out.length - 1], exp: nv, pts: (1 << nv) });
        gained += (1 << nv);
        vals = vals.slice(2);
      } else out.push(vals.shift());
    }
    while (out.length < 4) out.push(0);
    for (var j = 0; j < 4; j++) G.grid[line[j]] = out[j];
  }
  var moved = false;
  for (var i = 0; i < 16; i++) if (old[i] !== G.grid[i]) { moved = true; break; }
  if (!moved) return;
  G.score += gained;
  if (gained > 0) {
    TTG_snd("pop.wav", 85);
    for (var m = 0; m < merges.length; m++) {
      addPop(merges[m].cell, merges[m].exp);
      burst(merges[m].cell, merges[m].exp);
      popup("+" + merges[m].pts, merges[m].cell);
    }
  }
  if (!G.won) {
    for (var i = 0; i < 16; i++) if (G.grid[i] >= 11) {
      G.won = true; TTG_snd("win.wav", 90); popup("2048!", i); break;
    }
  }
  spawnTile();
  render();
  updateScore();
  if (!canMove()) gameOver();
}
function gameOver() {
  G.over = true;
  TTG_snd("gameover.wav", 80);
  var coins = Math.floor(G.score / 50), xp = Math.floor(G.score / 10);
  S.coins += coins; S.xp += xp; S.pinchGames += 1;
  var nb = G.score > S.pinchBest;
  if (nb) S.pinchBest = G.score;
  TTG_save();
  G.pscore.setText("SCORE: " + G.score);
  G.pscore.setX(540); G.pscore.setY(830);
  G.pbest.setText(nb ? "NEW BEST!" : ("BEST: " + S.pinchBest));
  G.pbest.setX(540); G.pbest.setY(910);
  G.pcoins.setText("+" + coins + " COINS    +" + xp + " XP");
  G.pcoins.setX(540); G.pcoins.setY(980);
  G.panel.hide(false); G.ptitle.hide(false); G.pscore.hide(false);
  G.pbest.hide(false); G.pcoins.hide(false);
  TTG_one("AgainBtn").hide(false); TTG_one("PanelHomeBtn").hide(false);
}

/* ---------- per-frame ---------- */
var dt = gdjs.evtTools.runtimeScene.getElapsedTimeInSeconds(runtimeScene);
if (dt > 0.1) dt = 0.1;

var defs = G.over ? G.defs.concat(G.panelDefs) : G.defs;
var r = TTG_buttons(G, defs);

if (!G.over) {
  if (r.pressed && G.py > 420 && G.py < 1620) G.swiping = true;
  if (r.released && G.swiping) {
    G.swiping = false;
    var dx = r.x - G.px, dy = r.y - G.py;
    if (Math.abs(dx) > 70 || Math.abs(dy) > 70) {
      if (Math.abs(dx) > Math.abs(dy)) doMove(dx > 0 ? "R" : "L");
      else doMove(dy > 0 ? "D" : "U");
    }
  }
}

/* tweens (merge/spawn pops) */
for (var ti = G.tweens.length - 1; ti >= 0; ti--) {
  var tw = G.tweens[ti]; tw.t += dt;
  var k = tw.t / tw.dur;
  if (k >= 1) { tw.obj.setScale(tw.base); G.tweens.splice(ti, 1); }
  else tw.obj.setScale(tw.base * (1 + tw.amp * Math.sin(Math.PI * k)));
}
/* particles */
for (var pi = 0; pi < G.pparts.length; pi++) {
  var p = G.pparts[pi];
  if (p.life <= 0) continue;
  p.life -= dt;
  if (p.life <= 0) { p.obj.hide(true); continue; }
  p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 1500 * dt;
  p.obj.setX(p.x); p.obj.setY(p.y);
  var f = p.life / p.max;
  p.obj.setOpacity(Math.round(255 * f));
  p.obj.setScale(0.4 + 0.6 * f);
}
/* score popups */
for (var qi = 0; qi < G.ppops.length; qi++) {
  var pp = G.ppops[qi];
  if (!pp.active) continue;
  pp.t += dt;
  var q2 = pp.t / pp.dur;
  if (q2 >= 1) { pp.active = false; pp.obj.hide(true); continue; }
  pp.obj.setY(pp.y0 - 90 * q2);
  pp.obj.setOpacity(Math.round(255 * (1 - q2)));
}
})();

